import{_ as t,a0 as p,w as d,s as o,ao as c,I as l,x as e,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在 Linux 終端上使用行編輯器 ed | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 終端上使用行編輯器 ed | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 終端上使用行編輯器 ed | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 終端上使用行編輯器 ed | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20201212 Power up your Linux terminal text editor with ed","title":"在 Linux 終端上使用行編輯器 ed","tag":"202204","desc":""},"relativePath":"202204/20201212 Power up your Linux terminal text editor with ed.md","filePath":"[post].md"}'),h={name:"202204/20201212 Power up your Linux terminal text editor with ed.md"};function r(g,s,u,k,b,m){const a=p("Link");return d(),o("div",null,[s[15]||(s[15]=c(`<h1 id="在-linux-終端上使用行編輯器-ed" tabindex="-1">在 Linux 終端上使用行編輯器 ed <a class="header-anchor" href="#在-linux-終端上使用行編輯器-ed" aria-label="Permalink to “在 Linux 終端上使用行編輯器 ed”">​</a></h1><blockquote><p>這個看似簡單的編輯器為用户提供了許多易於學習和使用的命令。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202204/04/145334l9w92ngiccginicn.jpg" alt=""></p><p>GNU <code>ed</code> 命令是一個行編輯器。它被認為是標準的 Unix 文本編輯器，因為它是首個出現在 Unix 的文本編輯器，並且它曾經無處不在，你在任何一個 POSIX 系統中都能找到它（通常來説，你現在也可以）。在某種程度上，你可以很容易看出來它是第一個文本編輯器，因為它在許多方面的功能都十分基礎。和其他大多數的文本編輯器不同，它不會打開一個屬於自己的窗口或顯示區域，事實上，在默認情況下，它甚至不會提示用户輸入文字。從另一個方面來説，它在交互功能上的缺失也可以成為一個優點。它是一個多功能的編輯器，你可以用簡短的命令控制它，無論是在交互式的命令列中，還是在編寫的 shell 腳本里。</p><h3 id="安裝-ed" tabindex="-1">安裝 ed <a class="header-anchor" href="#安裝-ed" aria-label="Permalink to “安裝 ed”">​</a></h3><p>如果你正在使用 Linux 或者 BSD 的話，你很可能已經默認安裝了 <code>ed</code>（在 Linux 上是 GNU 版 <code>ed</code>，而在 BSD 上是 BSD 版 <code>ed</code>）。但是，一些極簡的環境可能沒有包括 <code>ed</code>，這也沒關係，你的發行版的軟件倉庫中很可能有 <code>ed</code> 可供下載。macOS 默認安裝了 BSD 版 <code>ed</code>。</p><h3 id="啓動-ed" tabindex="-1">啓動 ed <a class="header-anchor" href="#啓動-ed" aria-label="Permalink to “啓動 ed”">​</a></h3><p>當你啓動 <code>ed</code> 的時候，你的終端提示符不見了，看起來好像是 <code>ed</code> 停止運行了。其實它沒有，它只是在等待你輸入指令而已。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ed</span></span></code></pre></div><p>為使 <code>ed</code> 顯示更詳細的信息，你可以輸入命令 <code>p</code> 讓它返回一個提示符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ed</span></span>
<span class="line"><span>p</span></span>
<span class="line"><span>?</span></span></code></pre></div><p>這個問號（<code>?</code>）是默認的 <code>ed</code> 提示符。</p><h3 id="緩衝區" tabindex="-1">緩衝區 <a class="header-anchor" href="#緩衝區" aria-label="Permalink to “緩衝區”">​</a></h3><p>當 <code>ed</code> 激活時，你其實是在和一個叫 <ruby>緩衝區<rt>buffer</rt></ruby> 的東西打交道。緩衝區是內存中的一塊區域。你並不會直接編輯文件，而是在編輯它對應的緩衝區。當你退出 <code>ed</code> 卻沒有把修改保存到磁盤的文件上時，所有的修改都會丟失，因為它們只在緩衝區裏存在。（這對於一個已經習慣了初始的 <ruby>草圖緩衝區<rt>scratch buffer</rt></ruby> 的資深 Emacs 用户可能很耳熟。）</p><h3 id="使用-ed-輸入文本" tabindex="-1">使用 ed 輸入文本 <a class="header-anchor" href="#使用-ed-輸入文本" aria-label="Permalink to “使用 ed 輸入文本”">​</a></h3><p>啓動 <code>ed</code> 後，你處於命令模式。這意味着你可以向編輯器發送指令，比如讓它顯示一個提示符，而不是空白區域。你可以使用 <code>a</code> 命令開始附加文本到當前的緩衝區，使用一個實心的點 <code>.</code> 來終止輸入。比如，下面的這個例子往緩衝區裏附加了兩行文字（“hello world” 和 “hello ed”）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?</span></span>
<span class="line"><span>a</span></span>
<span class="line"><span>hello world</span></span>
<span class="line"><span>hello ed</span></span>
<span class="line"><span>.</span></span></code></pre></div><p>使用點 <code>.</code> 終止輸入後，你將回到命令模式。</p><h3 id="查看緩衝區" tabindex="-1">查看緩衝區 <a class="header-anchor" href="#查看緩衝區" aria-label="Permalink to “查看緩衝區”">​</a></h3><p>怎樣查看當前緩衝區裏都有什麼呢？你可以輸入想要查看的行號，也可以使用 <code>,p</code> 命令來顯示所有的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>hello world</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>hello ed</span></span>
<span class="line"><span>,p</span></span>
<span class="line"><span>hello world</span></span>
<span class="line"><span>hello ed</span></span></code></pre></div><h3 id="寫入文件" tabindex="-1">寫入文件 <a class="header-anchor" href="#寫入文件" aria-label="Permalink to “寫入文件”">​</a></h3><p>如果你現在對文本很滿意，你可以使用 <code>w</code> 命令把緩衝區寫入到文件中，後面跟上目標文件名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?</span></span>
<span class="line"><span>w example.txt</span></span>
<span class="line"><span>19</span></span></code></pre></div><p>寫操作後顯示的那個數字代表着寫入到文件中的字符數。</p><h3 id="讀取文件" tabindex="-1">讀取文件 <a class="header-anchor" href="#讀取文件" aria-label="Permalink to “讀取文件”">​</a></h3><p>除了使用 <code>ed</code> 來讀取文本，你也可以使用 <code>r</code> 命令把一個已經存在的文件加載到到緩衝區裏：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?</span></span>
<span class="line"><span>r myfile.txt</span></span></code></pre></div><p>另外，你也可以在啓動 <code>ed</code> 時，在它後面加上你想要加載到緩衝區裏的文件名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ed myfile.txt</span></span></code></pre></div><h3 id="編輯緩衝區" tabindex="-1">編輯緩衝區 <a class="header-anchor" href="#編輯緩衝區" aria-label="Permalink to “編輯緩衝區”">​</a></h3><p>鑑於 <code>ed</code> 是一個文本編輯器，你當然可以使用一種特殊的語法來編輯緩衝區裏的文本。使用 <code>sed</code> 或 <code>vim</code> 的用户或許會覺得這個語法很熟悉。假設現在緩衝區裏已經加載了一個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ed myfile.txt</span></span>
<span class="line"><span>,p</span></span>
<span class="line"><span>This is an example document.</span></span>
<span class="line"><span>There is some text, but not much.</span></span>
<span class="line"><span>There is some errors, but not much.</span></span></code></pre></div><p>如果你要把第一句話中的 <code>document</code> 修改為 <code>file</code>，你可以先選擇目標行（<code>1</code>），然後使用 <code>s</code> 命令調用搜索函數，後面跟着搜索文本和替換文本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>This is an example document.</span></span>
<span class="line"><span>s/document/file/</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>This is an example file.</span></span></code></pre></div><p>如果你要編輯其他行，步驟也是一樣的，只需提供一個不同的行號即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>?</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>There is some errors, but not much.</span></span>
<span class="line"><span>s/is/are/</span></span>
<span class="line"><span>s/much/many/</span></span></code></pre></div><p>你可以使用 <code>,p</code> 命令來看到你對緩衝區的歷史編輯記錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>This is an example file.</span></span>
<span class="line"><span>There is some text, but not much.</span></span>
<span class="line"><span>There are some errors, but not many.</span></span></code></pre></div><p>當然，這些修改只存在於緩衝區裏。你如果在 <code>ed</code> 編輯器外查看這個文件，你只會看到原始的文本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat myfile.txt</span></span>
<span class="line"><span>This is an example document.</span></span>
<span class="line"><span>There is some text, but not much.</span></span>
<span class="line"><span>There is some errors, but not much.</span></span></code></pre></div><p>如果你要把這些修改保存迴文件中，使用 <code>w</code> 命令即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>w myfile.txt</span></span>
<span class="line"><span>258</span></span></code></pre></div><h3 id="清空緩衝區" tabindex="-1">清空緩衝區 <a class="header-anchor" href="#清空緩衝區" aria-label="Permalink to “清空緩衝區”">​</a></h3><p>如果想要得到一個新的緩衝區，以此來打開一個新的文件，或者把一個新的文件加載到不同的環境中，你可以使用 <code>c</code> 命令。使用這個清空緩衝區後，什麼也不會輸出，因為緩衝已經是空的了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c</span></span>
<span class="line"><span>,p</span></span></code></pre></div><h3 id="退出" tabindex="-1">退出 <a class="header-anchor" href="#退出" aria-label="Permalink to “退出”">​</a></h3><p>如果要退出當前的 <code>ed</code> 會話，你可以使用 <code>q</code> 命令。它並不會給你一個保存緩衝區的機會，所以你要確保自己在這之前執行了保存操作。</p><h3 id="嘗試一下-ed-吧" tabindex="-1">嘗試一下 ed 吧 <a class="header-anchor" href="#嘗試一下-ed-吧" aria-label="Permalink to “嘗試一下 ed 吧”">​</a></h3><p><code>ed</code> 還可以做到很多事情，學習 <code>ed</code> 可以讓你知道它和部分的 <code>vim</code> 是如何工作的。我並沒有嘗試使用 <code>ed</code> 來寫這篇文章，老實説，我也不認為它是通常意義上的最佳文本編輯器。但是，<code>ed</code> 仍然是一個出色的編輯器。通過閲讀它的文檔，你可以很輕鬆地學會它。在 GNU 系統上，你可以使用 <code>info ed</code> 來查看它的操作手冊。</p><hr>`,51)),l("p",null,[s[1]||(s[1]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/20/12/gnu-ed"},{default:i(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/20/12/gnu-ed",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[2]||(s[2]=[e("Seth Kenlon",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),n(a,{href:"https://github.com/lkxed"},{default:i(()=>[...s[4]||(s[4]=[e("lkxed",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const C=t(h,[["render",r]]);export{y as __pageData,C as default};
